<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\BankMatch; use App\Models\BankTransaction; use App\Models\CompanyBankAccount; use App\Models\OwnerTransfer; use App\Models\Payment; use App\Services\AuditService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class BankReconciliationController extends Controller {
 public function accounts(Request $r):JsonResponse{$items=CompanyBankAccount::where('organization_id',$r->attributes->get('organization_id'))->when($r->boolean('active'),fn($q)=>$q->where('status','active'))->orderBy('bank_name')->get()->map(fn($a)=>$this->accountData($a));return $this->success(['items'=>$items]);}
 public function transactions(Request $r):JsonResponse{$items=BankTransaction::where('organization_id',$r->attributes->get('organization_id'))->with('matches')->when($r->filled('status'),fn($q)=>$q->where('status',$r->string('status')->toString()))->orderByDesc('booked_date')->get()->map(fn($t)=>$this->transactionData($t));return $this->success(['items'=>$items]);}
 public function import(Request $r):JsonResponse{$d=$r->validate(['bankAccountId'=>['required','uuid'],'filename'=>['required','string','max:255'],'fileHash'=>['required','string','size:64'],'transactions'=>['required','array','min:1'],'transactions.*.bookedDate'=>['required','date'],'transactions.*.valueDate'=>['nullable','date'],'transactions.*.amount'=>['required','numeric','gt:0'],'transactions.*.direction'=>['required','in:inbound,outbound'],'transactions.*.externalReference'=>['required','string','max:150','distinct']]);$org=$r->attributes->get('organization_id');$actor=$r->user()->id;$result=DB::transaction(function()use($d,$org,$actor){CompanyBankAccount::where('organization_id',$org)->lockForUpdate()->findOrFail($d['bankAccountId']);if(DB::table('bank_imports')->where('bank_account_id',$d['bankAccountId'])->where('file_hash',$d['fileHash'])->lockForUpdate()->exists())abort(409,'تم استيراد هذا الملف سابقاً.');$importId=(string)Str::uuid();DB::table('bank_imports')->insert(['id'=>$importId,'organization_id'=>$org,'bank_account_id'=>$d['bankAccountId'],'filename'=>$d['filename'],'file_hash'=>$d['fileHash'],'imported_by'=>$actor,'imported_at'=>now()]);$created=[];foreach($d['transactions'] as $row){if(BankTransaction::where('bank_account_id',$d['bankAccountId'])->where('external_reference',$row['externalReference'])->lockForUpdate()->exists())abort(409,'يوجد مرجع حركة مكرر في هذا الحساب.');$t=BankTransaction::create(['id'=>(string)Str::uuid(),'organization_id'=>$org,'bank_account_id'=>$d['bankAccountId'],'bank_import_id'=>$importId,'booked_date'=>$row['bookedDate'],'value_date'=>$row['valueDate']??null,'amount'=>$row['amount'],'direction'=>$row['direction'],'external_reference'=>$row['externalReference'],'status'=>'unmatched']);$created[]=$this->transactionData($t->load('matches'));}AuditService::record($org,$actor,'bank_import.created','bank_import',$importId,null,['filename'=>$d['filename'],'count'=>count($created)]);return ['id'=>$importId,'transactions'=>$created];});return $this->success($result,[],201);}
 public function match(Request $r):JsonResponse{$d=$r->validate(['bankTransactionId'=>['required','uuid'],'paymentId'=>['required_without:ownerTransferId','nullable','uuid'],'ownerTransferId'=>['required_without:paymentId','nullable','uuid'],'amount'=>['required','numeric','gt:0']]);if(($d['paymentId']??null)&&($d['ownerTransferId']??null))abort(422,'اختر دفعة أو تحويلاً واحداً فقط.');$org=$r->attributes->get('organization_id');$actor=$r->user()->id;$match=DB::transaction(function()use($d,$org,$actor){$t=BankTransaction::where('organization_id',$org)->with('matches')->lockForUpdate()->findOrFail($d['bankTransactionId']);$isPayment=(bool)($d['paymentId']??null);if($isPayment&&$t->direction!=='inbound')abort(409,'لا تطابق الدفعة مع حركة صادرة.');if(!$isPayment&&$t->direction!=='outbound')abort(409,'لا تطابق التحويل مع حركة واردة.');$target=$isPayment?Payment::where('organization_id',$org)->lockForUpdate()->findOrFail($d['paymentId']):OwnerTransfer::query()->whereKey($d['ownerTransferId'])->whereIn('settlement_id',DB::table('owner_settlements')->where('organization_id',$org)->select('id'))->lockForUpdate()->firstOrFail();if($target->status!==($isPayment?'confirmed':'confirmed'))abort(409,'السند غير مؤكد.');$tm=(float)$t->matches->sum('amount');$column=$isPayment?'payment_id':'owner_transfer_id';$used=(float)DB::table('bank_matches')->join('bank_transactions','bank_transactions.id','=','bank_matches.bank_transaction_id')->where('bank_transactions.organization_id',$org)->where('bank_matches.'.$column,$target->id)->lockForUpdate()->sum('bank_matches.amount');if($tm+(float)$d['amount']>(float)$t->amount||$used+(float)$d['amount']>(float)$target->amount)abort(409,'قيمة المطابقة تتجاوز الرصيد المتبقي.');$m=BankMatch::create(['id'=>(string)Str::uuid(),'bank_transaction_id'=>$t->id,'payment_id'=>$isPayment?$target->id:null,'owner_transfer_id'=>$isPayment?null:$target->id,'amount'=>$d['amount'],'matched_by'=>$actor,'matched_at'=>now()]);$total=$tm+(float)$d['amount'];$t->update(['status'=>$total>=(float)$t->amount?'matched':'partially_matched']);AuditService::record($org,$actor,'bank_match.created','bank_match',$m->id,null,['bankTransactionId'=>$t->id,$isPayment?'paymentId':'ownerTransferId'=>$target->id,'amount'=>$d['amount']]);return $m;});return $this->success($this->matchData($match),[],201);}
 public function unmatch(Request $r,string $id):JsonResponse{$d=$r->validate(['reason'=>['required','string','min:5','max:1000']]);$org=$r->attributes->get('organization_id');$actor=$r->user()->id;DB::transaction(function()use($id,$d,$org,$actor){$m=BankMatch::whereKey($id)->lockForUpdate()->firstOrFail();$t=BankTransaction::where('organization_id',$org)->with('matches')->lockForUpdate()->findOrFail($m->bank_transaction_id);$before=$this->matchData($m);$m->delete();$remaining=(float)BankMatch::where('bank_transaction_id',$t->id)->sum('amount');$t->update(['status'=>$remaining===0.0?'unmatched':($remaining>=(float)$t->amount?'matched':'partially_matched')]);AuditService::record($org,$actor,'bank_match.deleted','bank_match',$id,$before,['reason'=>$d['reason']]);});return response()->json([],204);}
 private function accountData(CompanyBankAccount $a):array{return ['id'=>$a->id,'bankName'=>$a->bank_name,'accountName'=>$a->account_name,'iban'=>$a->iban,'status'=>$a->status];}
 private function matchData(BankMatch $m):array{return ['id'=>$m->id,'bankTransactionId'=>$m->bank_transaction_id,'paymentId'=>$m->payment_id,'ownerTransferId'=>$m->owner_transfer_id,'amount'=>(float)$m->amount,'matchedAt'=>$m->matched_at];}
 private function transactionData(BankTransaction $t):array{$matched=(float)$t->matches->sum('amount');return ['id'=>$t->id,'bankAccountId'=>$t->bank_account_id,'bookedDate'=>$t->booked_date,'valueDate'=>$t->value_date,'amount'=>(float)$t->amount,'direction'=>$t->direction,'externalReference'=>$t->external_reference,'status'=>$t->status,'matchedAmount'=>$matched,'remainingAmount'=>max(0,(float)$t->amount-$matched),'matches'=>$t->matches->map(fn($m)=>$this->matchData($m))->values()];}
}
